import {VirtualBluetooth} from './bluetooth-model.js';
export function attachBluetooth(runtime,engine,project){let observing=false,disposed=false;const bt=new VirtualBluetooth({cpu:runtime.cpu,solution:()=>engine.solution,changed:()=>{if(!disposed)engine.setDrivers('$bluetooth',bt.drivers());}});const observe=()=>{if(observing||disposed)return;observing=true;try{bt.observe();}finally{observing=false;}};const unsubscribe=engine.subscribe(observe);bt.update(project);return{command(d){const result=bt.command(d);observe();return result;},snapshot:()=>bt.snapshot(),updateProject(p){bt.update(p);observe();},dispose(){disposed=true;unsubscribe();bt.dispose();engine.setDrivers('$bluetooth',[]);}};}
